using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedWeldingEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedWelding Effect")]
public class CorruptedWeldingEffect : Effect
{
	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		CorruptedAnimalCorruptionStats component = effectOwner.GetComponent<CorruptedAnimalCorruptionStats>();
		int num = (int)component.MaxCorruption + effectAmount;
		component.ModifyMaxCorruption(num, num, 0.5f);
	}
}
